export type ILowFundsTranslations = IYesNoPopup;
export type IIDVerificationTranslations = IYesNoPopup;
interface IYesNoPopup {
    header: string;
    message: string;
    yes: string;
    no: string;
}

export interface ISelfExclusionTranslations {
    header: string;
    message: string;
    closeGameLabel: string;
    logoutLabel: string;
}

export interface ISessionAlertsTranslations {
    tenMinuteWarning: {
        title: string;
        body: string;
        continueButton: string;
    };
    immediateLogout: {
        title: string;
        body: string;
        smallPrint: string;
        continueButton: string;
    };
    sessionNotification: {
        title: string;
        body: string;
        timeSpentLabel: string;
        moneySpentLabel: string;
        smallPrint: string;
        continueButton: string;
    };
    closeButton: string;
}

export interface IBonusInPlayTranslations {
    TITLE: string;
    MESSAGE: string;
    BTN_LABEL: string;
}

export interface ILoadingSpinnerTranslations {
    LOADING: string;
}

export interface IRequirements {
    body: string;
    length: string;
    startingCharacter: string;
    alphaNumeric: string;
}

export interface INicknameTranslations {
    title: string;
    body: string;
    screenName: string;
    submitButton: string;
    requirements: IRequirements;
    serverErrors: IServerErrorsTranslations;
    toast: string;
}

export interface IServerErrorsTranslations {
    [key: number]: { [key: string]: string };
    400: {
        MalformedRequest: string;
    },
    401: {
        NotAuthenticated: string;
    },
    403: {
        NotAuthorized: string;
    },
    405: {
        RequestBlocked: string;
    },
    422: {
        Unknown: string;
        EmptyOrNull: string;
        TooLong: string;
        TooShort: string;
        InvalidCharacters: string;
        DisallowedPrefix: string;
        UnacceptablePhrasing: string;
        NicknameInUse: string;
    },
    500: {
        ServerError: string;

    },
    0: {
        Generic: string;
    }
}
